package net.civeira.phylax.features.access.userfederatedidentity.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.userfederatedidentity.domain.UserFederatedIdentity;
import net.civeira.phylax.features.access.userfederatedidentity.domain.event.UserFederatedIdentityEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserFederatedIdentityEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserFederatedIdentityEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserFederatedIdentity entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
